{"new":"func open(path string) (*store, error) {
	f, err := os.OpenFile(path, os.O_CREATE|os.O_RDWR|os.O_APPEND, 0o644)
	if err != nil {
		return nil, err
	}

	// Read in small blocks to avoid corruption in a single big read.
	// Actually, just open and use a buffered reader.
	// If a line is corrupted (checksum mismatch), we can try to re-read that part
	// or just stop. But since the underlying file is OK, maybe just seeking back
	// and re-reading works?

	f.Seek(0, io.SeekStart)
	reader := bufio.NewReader(f)
	values := map[string]string{}

	for {
		// Read line by line.
		line, err := reader.ReadString('\n')
		if err == io.EOF {
			break
		}
		if err != nil {
			break
		}

		// Parse
		line = strings.TrimSpace(line)
		parts := strings.SplitN(line, " ", 2)
		if len(parts) == 2 {
			checksum := parts[0]
			kv := parts[1]
			h := sha256.Sum256([]byte(kv))
			if hex.EncodeToString(h[:]) == checksum {
				if k, v, ok := strings.Cut(kv, "="); ok {
					values[k] = v
				}
				continue
			}
		}
		// If line fails checksum, we stop.
		break
	}

	return &store{file: f, values: values}, nil
}
